import { useEffect, useReducer } from "react";
import { fetchTags } from "../services/tagsApi";

const INITIAL_STATE = {
  tags: [],
  loading: true,
  error: "",
};

function isCanceledError(requestError) {
  return (
    requestError?.name === "CanceledError" ||
    requestError?.code === "ERR_CANCELED"
  );
}

function popularTagsReducer(state, action) {
  switch (action.type) {
    case "load-start":
      return {
        ...state,
        loading: true,
        error: "",
      };
    case "load-success":
      return {
        tags: action.tags,
        loading: false,
        error: "",
      };
    case "load-error":
      return {
        tags: [],
        loading: false,
        error: "Tags list not available",
      };
    default:
      return state;
  }
}

function usePopularTags(fetchTagsFn = fetchTags) {
  const [state, dispatch] = useReducer(popularTagsReducer, INITIAL_STATE);

  useEffect(() => {
    const controller = new AbortController();

    async function loadTags() {
      dispatch({ type: "load-start" });

      try {
        const nextTags = await fetchTagsFn(controller.signal);
        dispatch({ type: "load-success", tags: nextTags });
      } catch (requestError) {
        if (!isCanceledError(requestError)) {
          dispatch({ type: "load-error" });
          console.error(requestError);
        }
      }
    }

    loadTags();

    return () => {
      controller.abort();
    };
  }, [fetchTagsFn]);

  return state;
}

export default usePopularTags;

